from pathlib import Path
import html,json
P=Path(__file__).resolve().parent
shots=[('Why an answer arrives in pieces','One request. Two different waits.','request','Initial wait → first token → streamed answer'),('Text becomes token IDs','Boundaries depend on the tokenizer.','tokens','Five words do not necessarily mean five tokens.'),('IDs become numerical vectors','Embeddings combine with position information.','vectors','The model transforms numerical representations.'),('Through transformer blocks','Attention and feedforward transformations','layers','The final prompt position scores a new token.'),('Choose the next token','Illustrative probabilities, not a measured run','bars','Likelihood does not guarantee factual correctness.'),('Attention uses context','Queries compare with keys and mix values.','attention','A causal mask prevents looking at future positions.'),('Store keys and values','Reuse previous computation at each layer.','cache','The KV cache is temporary context state.'),('Prefill processes the prompt','Many positions are processed within each layer.','grid','Populate the cache and score the first new token.'),('Decode extends the sequence','The new token uses its cached history.','decode','Ordinary decoding depends on earlier choices.'),('The bottleneck can change','Compute, memory and scheduling all matter.','compare','Measure the initial wait and the output rate.'),('Batch several requests','The scheduler fills available processing slots.','batch','Shared weights. Separate context state.'),('Follow the whole request','Choose an optimization for the measured delay.','summary','Tokenize → prefill → decode → stream')]
def b(x,y,w,h,s,fill='none',step=True):return f'<g class="{ "step" if step else "base"}"><rect x="{x}" y="{y}" width="{w}" height="{h}" fill="{fill}" stroke="currentColor" stroke-width="2"/><text x="{x+w/2}" y="{y+h/2+11}" text-anchor="middle">{html.escape(s)}</text></g>'
def a(x,y,u,v):return f'<path class="step" d="M{x} {y}L{u} {v}" fill="none" stroke="currentColor" stroke-width="3" marker-end="url(#arrow)"/>'
def d(k):
 if k in ['tokens','summary','request']:
  ss={'tokens':['The','capital','of','Japan','is'],'summary':['Tokenize','Prefill','Decode','Stream'],'request':['Your prompt','Model service','Text arrives']}[k];w=1300/len(ss)
  return ''.join(b(70+i*w,150,w-25,130,s,step=i>0) for i,s in enumerate(ss))
 if k=='vectors':return ''.join(b(70+i*280,30,230,60,s,step=False)+''.join(b(105+i*280,130+j*55,160,44,str(round(((i*7+j*3)%19-9)/10,1))) for j in range(5)) for i,s in enumerate(['The','capital','of','Japan','is']))
 if k=='layers':return ''.join(b(270,340-i*100,920,75,'Transformer block '+str(i+1),step=i>0) for i in range(4))
 if k=='bars':return ''.join(f'<g class="step"><text x="100" y="{105+i*100}">{s}</text><rect x="360" y="{65+i*100}" width="{n*10}" height="56" fill="currentColor"/><text x="{390+n*10}" y="{105+i*100}">{n}%</text></g>' for i,(s,n) in enumerate([('Tokyo',72),('Kyoto',18),('Other',10)]))
 if k=='attention':return b(50,170,230,100,'Query',step=False)+''.join(b(510,30+i*140,230,90,s)+a(285,220,500,75+i*140)+a(745,75+i*140,1045,220) for i,s in enumerate(['Key 1','Key 2','Key 3']))+b(1055,165,360,110,'Weighted values')
 if k in ['cache','grid','decode']:
  out=''
  for j in range(4):
   out+=f'<text x="20" y="{90+j*85}">Layer {4-j}</text>'
   for i in range(6):out+=b(210+i*190,45+j*85,165,62,'K · V' if i<5 or k=='decode' else '', '#d9d6ef' if i<5 else '#b4b0ed' if k=='decode' else 'none',step=j<3 or i==5)
  return out+''.join(f'<text x="{292+i*190}" y="430" text-anchor="middle">{s}</text>' for i,s in enumerate(['The','capital','of','Japan','is','Tokyo']))
 if k=='compare':return b(75,60,620,300,'',step=False)+b(785,60,620,300,'',step=False)+'<text x="385" y="145" text-anchor="middle">PREFILL</text><text x="1095" y="145" text-anchor="middle">DECODE</text><text class="step" x="385" y="245" text-anchor="middle">Often compute-heavy</text><text class="step" x="1095" y="245" text-anchor="middle">Often bandwidth-limited</text>'
 return ''.join(b(40,35+j*120,230,80,'Request '+str(j+1),step=False)+a(280,75+j*120,450,75+j*120)+b(470,35+j*120,920,80,'Shared batch · separate sequence state') for j in range(3))
css='''@font-face{font-family:SourceSerif;src:url(assets/fonts/source-serif-4-latin-400-normal.woff2)}@font-face{font-family:Inter;src:url(assets/fonts/inter-latin-400-normal.woff2)}#root{position:absolute;inset:0;background:#f4f0e2;color:#302cb5;font-family:Inter}.paper{position:absolute;inset:0;background-image:linear-gradient(#302cb508 1px,transparent 1px),linear-gradient(90deg,#302cb508 1px,transparent 1px);background-size:24px 24px}.label{position:absolute;left:130px;top:80px;font-size:28px;letter-spacing:3px}.brand{position:absolute;right:130px;top:80px;font-size:28px}h1{position:absolute;left:130px;top:165px;font-family:SourceSerif;font-weight:400;font-size:66px;line-height:1.15;width:1600px;margin:0}h2{position:absolute;left:130px;top:270px;font-size:28px;font-weight:400;margin:0}.hero{position:absolute;left:190px;top:360px;width:1540px;height:460px}svg text{font-family:SourceSerif;font-size:31px;fill:currentColor}.caption{position:absolute;left:190px;right:190px;bottom:145px;font-size:30px;text-align:center}.draft{position:absolute;left:130px;bottom:65px;font-size:28px;letter-spacing:1px}'''
mount=[]
for i,(title,sub,kind,caption) in enumerate(shots):
 sid=f'scene{i+1:02}';mount.append(f'<div id="{sid}" class="clip" data-composition-id="{sid}" data-composition-src="compositions/{sid}.html" data-start="{i*5}" data-duration="5" data-track-index="1" data-track-kind="graphics" data-width="1920" data-height="1080"></div>')
 body=f'<div class="paper"></div><div class="label">HOW LLM INFERENCE WORKS</div><div class="brand">WITHHAMMAD</div><h1>{title}</h1><h2>{sub}</h2><svg class="hero" data-hold="true" viewBox="0 0 1480 460"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8" fill="#302cb5"/></marker></defs>{d(kind)}</svg><div class="caption">{caption}</div><div class="draft">VISUAL PREVIEW · NARRATION PENDING</div>'
 (P/'compositions'/f'{sid}.html').write_text(f'<template><style>{css}</style><div id="root" data-composition-id="{sid}" data-width="1920" data-height="1080"><div id="{sid}-content" class="clip" data-start="0" data-duration="5">{body}</div></div><script>const tl=gsap.timeline({{paused:true}});tl.fromTo(".step",{{opacity:0}},{{opacity:1,duration:.45,stagger:.06,ease:"power2.out"}},.25);window.__timelines["{sid}"]=tl;</script></template>')
(P/'index.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><script src="assets/gsap.min.js"></script><style>*{margin:0}body{width:1920px;height:1080px;overflow:hidden}#root{position:absolute;inset:0}</style></head><body><div id="root" data-composition-id="main" data-start="0" data-duration="60" data-width="1920" data-height="1080">'+''.join(mount)+'</div><script>window.__timelines=window.__timelines||{};window.__timelines.main=gsap.timeline({paused:true});</script></body></html>')
(P/'SPEC.md').write_text('GOAL: Show prompt processing, next-token generation, KV caching and serving bottlenecks.\nOUTPUT: HyperFrames 1920x1080 30fps.\nTIME: 60-second visual proof, 12 scenes of 150 frames. Full 1566-word narration blocked on HeyGen 402 credits. Final durations must follow actual narration.\nLOOK: cream #f4f0e2, blue #302cb5; Source Serif 66px, Inter 28px; 24px grid at 3% opacity.\nMOTION: opacity reveals 0.45s, stagger .06s.\nBANNED: fake measured model outputs, universal bottleneck claims, accelerated owner voice, copied script.\nQA: 12 scene midpoints, text fit, illustrative labels and separate cached state.\n')
print('Built twelve scenes')
